function renderStats(){const p=planes[save.plane],next=planes.find(p=>p.xp>save.xp);$('#totalMiles').textContent=Math.round(save.miles).toLocaleString();$('#totalJobs').textContent=save.jobs;$('#credits').textContent=save.xp;$('#rank').textContent=`LEVEL 0${planes.filter(p=>save.xp>=p.xp).length}`;$('#planeName').textContent=p.name;$('#planeMaker').textContent=p.maker;$('.plane-watermark').textContent=p.short;$('#planeTier').textContent=`TIER 0${save.plane+1}`;$('#capacity').textContent=p.pax+' 人';$('#cargo').textContent=p.cargo.toLocaleString()+' kg';$('#cruise').textContent=p.speed+' km/h';$('#nextPlane').textContent=next?'解锁 '+next.name:'全机队已解锁';$('#xpLabel').textContent=next?`${save.xp} / ${next.xp} XP`:`${save.xp} XP · 王牌飞行员`;$('#xpBar').style.width=(next?Math.min(100,save.xp/next.xp*100):100)+'%';renderFleet();renderLog();if(previewPlane){previewScene.remove(previewPlane);dispose(previewPlane);previewPlane=makePlane(save.plane);previewScene.add(previewPlane)}}
