function earthTexture(){const c=document.createElement('canvas');c.width=2048;c.height=1024;const ctx=c.getContext('2d');ctx.fillStyle='#b8cfca';ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle='#c5d8cf';ctx.lineWidth=1;for(let x=0;x<2048;x+=85){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,1024);ctx.stroke()}for(let y=0;y<1024;y+=85){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(2048,y);ctx.stroke()}const shapes=landPolygons.map(p=>p[0]);shapes.forEach((pts,i)=>{ctx.beginPath();pts.forEach(([lon,lat],j)=>{const x=(lon+180)/360*2048,y=(90-lat)/180*1024;j?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();ctx.fillStyle=['#a7b993','#b5c39b','#cdd4b1','#acbd92'][i%4];ctx.fill();ctx.strokeStyle='#9daf8d';ctx.lineWidth=2;ctx.stroke()});const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t}
