const markers=cities.map((c,i)=>{const m=mesh(new THREE.SphereGeometry(.027,12,8),0xfaf7de);m.position.copy(ll(c.lat,c.lon));globeGroup.add(m);const el=document.createElement('div');el.className='map-label';el.textContent=c.name;$('#mapLabels').append(el);return{m,el}});let routeLine;function drawRoute(){if(routeLine){globeGroup.remove(routeLine);dispose(routeLine)}const t=tasks[selected],a=ll(cities[city].lat,cities[city].lon),b=ll(cities[t.i].lat,cities[t.i].lon),pts=[];for(let i=0;i<=80;i++){const f=i/80;pts.push(a.clone().lerp(b,f).normalize().multiplyScalar(2.19+Math.sin(f*Math.PI)*.37))}routeLine=new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineDashedMaterial({color:0xd78746,dashSize:.065,gapSize:.04}));routeLine.computeLineDistances();globeGroup.add(routeLine);markers.forEach((m,i)=>m.el.className='map-label'+(i===city?' origin':''))}
