$('#launch').onclick=()=>{const t=tasks[selected],p=planes[save.plane];if(t.type==='旅客'&&t.count>p.pax||t.weight>p.cargo){toast('当前机型运力不足，请切换飞机');return}startFlight()};
function startFlight(){mode='flight';paused=false;keys={};flight=createFlight(tasks[selected],city,planes[save.plane].speed);createWorld();$('#flight').classList.remove('hidden');$('#flightRoute').textContent=`${cities[city].name} → ${cities[flight.mission.i].name}`;$('#pause').textContent='Ⅱ 暂停';$('#flightProgress').textContent='0 / 8';$('#routeBar').style.width='0%';$('#cloudVeil').style.opacity=0;$('#landmarkLabel').style.display='none';$('#resultClose').textContent='继续探索世界 ↗';message('油门已设为 80% · 加速到 44 kt 后按 W 抬头',6500);resizeAll();updateFlight(0);startAudio();}
function message(text,duration=3500){$('#flightMessage').textContent=text;clearTimeout(message.timer);message.timer=setTimeout(()=>{if(!paused)$('#flightMessage').textContent=''},duration)}
function setPause(v){if(mode!=='flight')return;paused=v;keys={};$('#pause').textContent=paused?'▶ 继续':'Ⅱ 暂停';clearTimeout(message.timer);$('#flightMessage').textContent=paused?'已暂停 · 按 Esc 继续':'';updateAudio()}
